import '../showWorkFlow.css';

let ani = '';
export default {
    name: 'User',
    components: {},
    props: {
        noHover: {
            type: Boolean,
            default: false,
        },
        user: {
            type: Object,
            default() {
                return null;
            }
        },
        scrollY: {
            type: Number,
            default: 0
        },
        height: {
            type: String,
            default() {
                return '';
            }
        },
        flowHeight: {
            type: Number,
            default: 0
        }
    },
    data() {
        return {
            show: false,
            IE: false,
            current: 0,
            iconNow: 1,
            // 动画切换时间
            iconOverTime: 1,
            clientWidth: undefined,
            clientHeight: undefined,
            top: false,
            offsetY: undefined
        };
    },
    computed: {
        // 会签节点开关状态改变时，切换子流程会签的图标
        isCountersign() {
            return false;
        },
        mystyle() {
            return {
                'top': `${this.user.y}px`,
                'left': `${this.user.x}px`,
                'width': `${this.user.width}px`,
                'height': `${this.user.height}px`
            };
        },
        pStyle() {
            return {
                'top': `${this.user.height}px`,
                'left': `${this.user.width / 2 - this.user.name.length * 6}px`
            };
        },
        state() {
            if (this.user.state === 'finish') {
                return 'finish';
            } else if (this.user.state === 'complete') {
                return 'complete';
            } else if (this.user.state === 'reject') {
                return 'reject ';
            } else if (this.user.state === 'revoke') {
                return 'complete';
            } else if (this.user.state === 'suspend') {
                return 'suspend';
            } else if (this.user.state === 'overtime') {
                return 'overtime';
            } else {
                return 'todo';
            }
        },
        // userBorder() {
        //   if (this.user.state === 'finish') {
        //     return '#1F8AFF';
        //   } else if (this.user.state === 'complete') {
        //     return '#41CC8B';
        //   } else if (this.user.state === 'reject') {
        //     return '#FF5251 ';
        //   } else if (this.user.state === 'revoke') {
        //     return '#F77E5C';
        //   } else if (this.user.state === 'suspend') {
        //     return '#73D0FF';
        //   } else if (this.user.state === 'overtime') {
        //     return '#FF9F0D';
        //   } else {
        //     return '#CFDDEC';
        //   }
        // },
        // userContent() {
        //   if (this.user.state === 'finish') {
        //     return 'rgba(236,255,246,1)';
        //   } else if (this.user.state === 'complete') {
        //     return 'rgba(237,246,255,1)';
        //   } else if (this.user.state === 'reject') {
        //     return 'rgba(247, 126, 92, 0.1)';
        //   } else if (this.user.state === 'revoke') {
        //     return 'rgba(255,246,246,1)';
        //   } else if (this.user.state === 'suspend') {
        //     return 'rgba(115, 208, 255, 0.1)';
        //   } else if (this.user.state === 'overtime') {
        //     return 'rgba(255,246,233,1)';
        //   } else {
        //     return 'rgba(246,249,252,1)';
        //   }
        // },
        listStyle() {
            if (this.show) {
                return {
                    'top': `${this.user.height + 10}px`,
                    'left': `${-this.user.width}px`,
                    'display': 'block'
                }
            } else {
                return {
                    'top': `${this.user.height + 10}px`,
                    'left': `${-this.user.width}px`,
                    'display': 'none'
                }
            }
        },
        toplistStyle() {
            if (this.show) {
                return {
                    'bottom': `${this.user.height + 10}px`,
                    'left': `${-this.user.width}px`,
                    'display': 'block'
                }
            } else {
                return {
                    'bottom': `${this.user.height + 10}px`,
                    'left': `${-this.user.width}px`,
                    'display': 'none'
                }
            }
        },
        arrowlistStyle() {
            if (this.show) {
                return {
                    'top': `${this.user.height}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'block'
                }
            } else {
                return {
                    'top': `${this.user.height}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'none'
                }
            }
        },
        arrowinsidelistStyle() {
            if (this.show) {
                return {
                    'top': `${this.user.height + 1}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'block'
                }
            } else {
                return {
                    'top': `${this.user.height + 1}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'none'
                }
            }
        },
        arrowtoplistStyle() {
            if (this.show) {
                return {
                    'bottom': `${this.user.height}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'block'
                };
            } else {
                return {
                    'bottom': `${this.user.height}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'none'
                };
            }
        },
        arrowinsidetoplistStyle() {
            if (this.show) {
                return {
                    'bottom': `${this.user.height + 1}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'block'
                };
            } else {
                return {
                    'bottom': `${this.user.height + 1}px`,
                    'left': `${this.user.width / 3}px`,
                    'display': 'none'
                };
            }
        },
        completeOrNot() {
            const forbidBottom = (this.flowHeight - this.user.height + this.scrollY) < 230;
            const forbidTop = (this.user.y - this.scrollY) < 230;
            let num = 4;
            if (this.user.nodes) {
                if (this.user.nodes.state === 'complete') {
                    switch ((this.top || (!this.top && forbidBottom)) && !forbidTop) {
                        case true:
                            num = 3;
                            break;
                        case false:
                            num = 1;
                            break;
                    }
                } else {
                    switch ((this.top || (!this.top && forbidBottom)) && !forbidTop) {
                        case true:
                            num = 2;
                            break;
                        case false:
                            num = 0;
                            break;
                    }
                }
            }
            return num;
        }
    },

    mounted() {
        this.IE = false;
        if (this.user.state === 'overtime') {
            ani = setInterval(() => {
                this.animation('overtime');
            }, 100);
        } else if (this.user.state === 'complete') {
            ani = setInterval(() => {
                this.animation('complete');
            }, 100);
        }
        this.clientWidth = document.documentElement.clientWidth - 240;
        this.clientHeight = document.documentElement.clientHeight;
    },
    beforeUnmount() {
        if (ani !== '') {
            clearInterval(ani);
        }
    },
    methods: {
        filterTableData(id) {
            this.$emit('filterTableData', id);
        },
        touchmove(e) {
            // 获取起始坐标位置x
            const y = e.offsetY;
            if (y < this.user.height / 3) {
                this.top = true;
            } else {
                this.top = false;
            }
        },
        animation(data) {
            switch (data) {
                case 'overtime':
                    if (this.iconOverTime === 5) {
                        this.iconOverTime = 1;
                    } else {
                        this.iconOverTime++;
                    }
                    break;
                case 'complete':
                    if (this.iconNow === 5) {
                        this.iconNow = 1;
                    } else {
                        this.iconNow++;
                    }
                    break;
            }
        },
        showList() {
            if (this.show) {
                this.show = false;
            } else {
                this.show = true;
            }
        },
        changeCurrent(index) {
            if (this.current === index) {
                this.current = -1;
            } else {
                this.current = index;
            }
        }
    },
};
